"""Blender 3.6+/4.x: pildilt märgitud ruudunurgad -> ühendatud auto võrk.

425 külgvaate ankrut on käsitsi märgitud pildi pikslikoordinaatides.
3D-sügavus on hinnatud eest- ja pealtvaate silueti järgi.
Teine külg on peegeldatud; peidetud ristpinnad on hinnatud.
Punktide pildil märkimine pole algse mudeli täpsete vertexite taastamine.
Vaata punktid_algsel_pildil.png, et hinnata jäljenduse vastavust.
Scripting > Open > Run Script. Ei vaja scipy/numpy ega lisafaile.
"""
import math
from collections import defaultdict, deque

LONGITUDINAL = 80
PERIMETER = 64  # keep 64: wheel patch layout is calibrated to this grid
TRIANGULATE = False  # True: all faces become triangles
SHOW_POINT_CLOUD = False  # True: show loose vertices instead of the final mesh
POINT_RADIUS = 0.009
OUTPUT_BLEND = ""  # optional absolute path; empty = don't save automatically
COLLECTION_NAME = "AUTO_RUUDUNURGAD_V2"
# x (front negative), roof z, width multiplier
PROFILE = [(-2.1, 1.02, .87), (-1.9, 1.09, .96),
           (-1.15, 1.12, 1.0), (-.95, 1.16, 1.0),
           (-.25, 1.63, 1.0), (.2, 1.68, 1.0),
           (1.35, 1.66, 1.0), (1.75, 1.50, .98),
           (2.1, 1.10, .91)]


def profile(x):
    for a, b in zip(PROFILE, PROFILE[1:]):
        if a[0] <= x <= b[0]:
            t = (x-a[0])/(b[0]-a[0])
            return tuple(a[k]*(1-t)+b[k]*t for k in (1, 2))
    return PROFILE[-1][1:]


